'use strict';

function buildPullRequestArtifact(input = {}) {
  const mission = input.mission || {};
  const workspace = input.workspace || {};
  const delivery = input.delivery || {};
  const evidence = input.evidence || {};
  const changedFiles = Array.isArray(delivery.changedFiles) ? delivery.changedFiles : [];
  const title = String(input.title || mission.title || 'Krevyx mission delivery').slice(0, 200);
  const lines = [
    `## ${title}`,
    '',
    'Generated by Krevyx from a mission-scoped isolated worktree. Review and explicit user approval are required before remote Git actions.',
    '',
    '### Mission',
    `- Mission: ${mission.id || 'unknown'}`,
    `- Workspace: ${workspace.name || workspace.id || 'unknown'}`,
    `- Status: ${mission.status || 'unknown'}`,
    `- Tasks: ${Number(evidence.taskCount || 0)}`,
    '',
    '### Git delivery',
    `- Base SHA: ${delivery.baseSha || 'unknown'}`,
    `- Head SHA: ${delivery.headSha || 'unknown'}`,
    `- Diff SHA-256: ${delivery.diffHash || 'unknown'}`,
    `- Changed files: ${changedFiles.length}`,
  ];
  if (changedFiles.length) {
    for (const file of changedFiles.slice(0, 100)) lines.push(`  - ${file}`);
  } else {
    lines.push('  - none');
  }
  if (delivery.diffStat) {
    lines.push('', '### Diff stat', '```text', String(delivery.diffStat).slice(0, 8000), '```');
  }
  lines.push(
    '',
    '### Verification evidence',
    `- Agent runs: ${Number(evidence.agentRunCount || 0)}`,
    `- Verification runs: ${Number(evidence.verificationRunCount || 0)}`,
    `- Passed verification runs: ${Number(evidence.verificationPassed || 0)}`,
    `- Failed verification runs: ${Number(evidence.verificationFailed || 0)}`,
    `- Evidence records: ${Number(evidence.evidenceCount || 0)}`,
    '',
    '### Safety',
    '- Mission changes were produced in an isolated worktree.',
    '- This artifact is descriptive only and performs no remote Git action.',
  );
  return { title, body: lines.join('\n') };
}

module.exports = { buildPullRequestArtifact };
